solution.solution.lua:
function capitalize(s)
    return s:sub(1, 1):upper() .. s:sub(2):lower()
end

function starts_with(s, prefix)
    return s:sub(1, #prefix) == prefix
end

function ends_with(s, suffix)
    return suffix == "" or s:sub(-#suffix) == suffix
end

function count_char(s, c)
    local n = 0
    for i = 1, #s do
        if s:sub(i, i) == c then n = n + 1 end
    end
    return n
end

function is_palindrome(s)
    local letters = {}
    for i = 1, #s do
        local ch = s:sub(i, i)
        if ch:lower() ~= ch:upper() then letters[#letters + 1] = ch:lower() end
    end
    local text = table.concat(letters)
    return text == text:reverse()
end
